select id, profile_id, url, is_primary, sort_order, status, created_at, updated_at from cm_profile_photos where profile_id in
#{pid}
and status = 'approved' order by sort_order asc

select profile_id as profileId, language_code as languageCode from cm_profile_languages where profile_id in
#{pid}
order by language_code

select id, profile_id as profileId, field_name as fieldName, locale, value, source, provider, status, created_at as createdAt, updated_at as updatedAt from cm_profile_localized_fields where profile_id in
#{pid}
and field_name in
#{fn}
and status = 'ready' and trim(value) != '' order by profile_id, field_name, case locale when #{locale} then 0 when 'zh' then 1 when 'en' then 2 else 3 end

select id, profile_id as profileId, field_name as fieldName, item_order as itemOrder, locale, value, source, provider, status, created_at as createdAt, updated_at as updatedAt from cm_profile_localized_items where profile_id in
#{pid}
and field_name in
#{fn}
and status = 'ready' and trim(value) != '' order by profile_id, field_name, item_order, case locale when #{locale} then 0 when 'zh' then 1 when 'en' then 2 else 3 end

select profile_id as profileId, value_code as valueCode
from cm_profile_relationship_values
where profile_id = #{profileId}

select id, user_id as userId, profile_id as profileId,
       created_at as createdAt, updated_at as updatedAt
from cm_favorite_profiles
where user_id = #{userId}
  and profile_id = #{profileId}
limit 1

select id, profile_id, url, is_primary, sort_order, status, created_at, updated_at from cm_profile_photos where profile_id in
#{pid}
order by sort_order asc

select count(1) from cm_private_introduction_requests
where target_profile_id = #{profileId}
  and status in ('requested', 'accepted')

